import { buildSession } from "@/lib/telemetry/build-session";
import { computeCompulsion } from "@/lib/telemetry/compulsion";
import type { CognitiveResult, FocusAfter, GuardianEvent, Mood, MoodLog, UserProfile, VideoSession, ViewEvent, WatchReason } from "@/types";

/**
 * Deterministic 14-day demo persona ("Aarav"): late-night, compulsive sessions early on that gradually improve.
 * Every number is generated by the same telemetry + compulsion model the live app uses, so the dashboard,
 * Coach and Autopsy show consistent, explainable data. Clearly flagged as demo data in the UI.
 */

function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const topics = ["science facts", "funny moments", "study motivation", "satisfying", "mind blowing facts", "tech explained"];
const titles = [
  "Why the sky is blue, in 30 seconds",
  "Cat fails compilation #214",
  "How to study for 4 hours without burning out",
  "Oddly satisfying pressure wash",
  "Black holes explained simply",
  "10 keyboard tricks you need",
  "Street food in under a minute",
  "Mind-blowing optical illusion",
  "Perfect gym transition",
  "Tiny home tour"
];

interface Plan {
  daysAgo: number;
  hour: number;
  minutes: number;
  urge: number;
  moodBefore: Mood;
  moodAfter: Mood;
  reason: WatchReason;
  focusAfter: FocusAfter;
  goal?: string;
  /** Mean dwell per reel at the start / end of the session (seconds). */
  dwellStart: number;
  dwellEnd: number;
}

const plans: Plan[] = [
  { daysAgo: 13, hour: 23, minutes: 34, urge: 9, moodBefore: "Stressed", moodAfter: "Anxious", reason: "Stress relief", focusAfter: "Less focused", dwellStart: 11, dwellEnd: 2.5 },
  { daysAgo: 12, hour: 0, minutes: 29, urge: 8, moodBefore: "Bored", moodAfter: "Tired", reason: "Boredom", focusAfter: "Less focused", dwellStart: 10, dwellEnd: 2.8 },
  { daysAgo: 10, hour: 22, minutes: 31, urge: 8, moodBefore: "Procrastinating", moodAfter: "Anxious", reason: "Procrastination", focusAfter: "Less focused", dwellStart: 12, dwellEnd: 3 },
  { daysAgo: 9, hour: 23, minutes: 26, urge: 7, moodBefore: "Stressed", moodAfter: "Stressed", reason: "Habit", focusAfter: "Less focused", dwellStart: 11, dwellEnd: 3.2 },
  { daysAgo: 7, hour: 21, minutes: 24, urge: 7, moodBefore: "Bored", moodAfter: "Neutral", reason: "Entertainment", focusAfter: "Same", dwellStart: 13, dwellEnd: 4 },
  { daysAgo: 6, hour: 22, minutes: 21, urge: 6, moodBefore: "Tired", moodAfter: "Tired", reason: "Habit", focusAfter: "Same", dwellStart: 14, dwellEnd: 5 },
  { daysAgo: 5, hour: 20, minutes: 18, urge: 6, moodBefore: "Anxious", moodAfter: "Neutral", reason: "Stress relief", focusAfter: "Same", goal: "calm down before studying", dwellStart: 15, dwellEnd: 7 },
  { daysAgo: 4, hour: 19, minutes: 16, urge: 5, moodBefore: "Neutral", moodAfter: "Happy", reason: "Learning", focusAfter: "More focused", goal: "learn something quick", dwellStart: 16, dwellEnd: 9 },
  { daysAgo: 3, hour: 21, minutes: 14, urge: 5, moodBefore: "Stressed", moodAfter: "Neutral", reason: "Stress relief", focusAfter: "Same", goal: "unwind for 10 minutes", dwellStart: 17, dwellEnd: 10 },
  { daysAgo: 2, hour: 18, minutes: 12, urge: 4, moodBefore: "Bored", moodAfter: "Happy", reason: "Entertainment", focusAfter: "More focused", dwellStart: 18, dwellEnd: 11 },
  { daysAgo: 1, hour: 20, minutes: 11, urge: 4, moodBefore: "Neutral", moodAfter: "Happy", reason: "Learning", focusAfter: "More focused", goal: "science facts before bed", dwellStart: 19, dwellEnd: 13 },
  { daysAgo: 0, hour: 17, minutes: 9, urge: 3, moodBefore: "Procrastinating", moodAfter: "Neutral", reason: "Motivation", focusAfter: "More focused", goal: "get motivated to study", dwellStart: 20, dwellEnd: 14 }
];

export interface PersonaData {
  profile: UserProfile;
  sessions: VideoSession[];
  moodLogs: MoodLog[];
  cognitiveResult: CognitiveResult;
}

export function generatePersona(now: Date = new Date(), seed = 42): PersonaData {
  const rand = mulberry32(seed);
  const profile: UserProfile = {
    name: "Aarav",
    age: 20,
    studentStatus: "college",
    dailyUsageMinutes: 150,
    mainPlatform: "YouTube Shorts",
    studyHours: 2,
    sleepHours: 5.5,
    lateNightUsage: "Often",
    losesTrackOfTime: "Often",
    unintentionalOpening: "Sometimes",
    createdAt: new Date(now.getTime() - 14 * 86_400_000).toISOString()
  };

  const sessions: VideoSession[] = [];
  const moodLogs: MoodLog[] = [];

  plans.forEach((plan, planIndex) => {
    const start = new Date(now);
    start.setDate(start.getDate() - plan.daysAgo);
    start.setHours(plan.hour, Math.floor(rand() * 50), 0, 0);
    if (start.getTime() > now.getTime()) start.setTime(now.getTime() - (plan.minutes + 5) * 60_000);
    const startedAtMs = start.getTime();
    const totalMs = plan.minutes * 60_000;
    const plannedMinutes = 10;

    const views: ViewEvent[] = [];
    let clock = 0;
    let index = 0;
    let peak = 0;
    const guardianEvents: GuardianEvent[] = [];
    let lastGuardianAt = -Infinity;

    while (clock < totalMs) {
      const progress = clock / totalMs;
      const meanDwell = plan.dwellStart + (plan.dwellEnd - plan.dwellStart) * progress;
      // Quick skips are common early on and fade as the habit improves.
      const skipChance = 0.35 - 0.29 * (planIndex / (plans.length - 1));
      const dwellSec = rand() < skipChance ? 0.9 + rand() * 1.9 : Math.max(0.8, meanDwell * (0.45 + rand() * 1.1));
      const dwellMs = Math.min(dwellSec * 1000, totalMs - clock + 500);
      const durationSec = 18 + Math.floor(rand() * 32);
      const watchedMs = dwellMs * (0.82 + rand() * 0.16);
      const topic = topics[(planIndex + index) % topics.length];
      views.push({
        videoId: `persona${planIndex}x${index}`.padEnd(11, "0").slice(0, 11),
        title: titles[(planIndex * 3 + index) % titles.length],
        topic,
        index,
        startedAtMs: startedAtMs + clock,
        dwellMs: Math.round(dwellMs),
        watchedMs: Math.round(watchedMs),
        durationSec,
        completion: Math.min(1, watchedMs / 1000 / durationSec),
        loops: dwellSec > durationSec ? 1 : 0,
        skippedEarly: dwellMs < 3000,
        liked: rand() < (plan.dwellEnd > 8 ? 0.12 : 0.04),
        soundOn: rand() < 0.4
      });
      clock += dwellMs;
      index += 1;

      const reading = computeCompulsion({
        views,
        elapsedSec: clock / 1000,
        plannedMinutes,
        hour: new Date(startedAtMs + clock).getHours(),
        moodBefore: plan.moodBefore
      });
      peak = Math.max(peak, reading.index);
      if (reading.index >= 55 && clock - lastGuardianAt > 4 * 60_000 && guardianEvents.length < 3) {
        lastGuardianAt = clock;
        const improving = planIndex >= 7;
        guardianEvents.push({
          at: new Date(startedAtMs + clock).toISOString(),
          compulsion: reading.index,
          severity: guardianEvents.length === 0 ? "gentle" : "firm",
          headline: guardianEvents.length === 0 ? "You're swiping on autopilot" : "Time to take a breath",
          message: "Your recent reels held you for only a few seconds each. Take a moment and choose what you want next.",
          evidence: reading.evidence,
          action: guardianEvents.length === 0 ? "breathing_break" : "end_session",
          source: "offline",
          response: improving || guardianEvents.length === 0 ? "accepted" : "dismissed"
        });
      }
    }

    const session = buildSession({
      id: `persona_session_${planIndex + 1}`,
      config: { plannedMinutes, moodBefore: plan.moodBefore, reason: plan.reason, goal: plan.goal, queries: [] },
      startedAtMs,
      endedAtMs: startedAtMs + totalMs,
      views,
      guardianEvents,
      mindfulPauseCount: guardianEvents.filter((event) => event.response === "accepted" && event.action === "breathing_break").length,
      peakCompulsion: peak,
      completed: true,
      post: { moodAfter: plan.moodAfter, urge: plan.urge, focusAfter: plan.focusAfter }
    });
    sessions.push(session);
    moodLogs.push({
      id: `persona_mood_${planIndex + 1}`,
      moodBefore: plan.moodBefore,
      moodAfter: plan.moodAfter,
      reason: plan.reason,
      urgeToContinueScore: plan.urge,
      exceededPlannedTime: session.exceededPlannedTime,
      focusAfter: plan.focusAfter,
      createdAt: new Date(startedAtMs + totalMs).toISOString()
    });
  });

  const cognitiveResult: CognitiveResult = {
    reactionTimeMs: 405,
    reactionEarlyClicks: 1,
    memoryScore: 62,
    memoryWordsRemembered: 5,
    stroopScore: 68,
    stroopAccuracy: 80,
    stroopAverageMs: 890,
    updatedAt: new Date(now.getTime() - 86_400_000).toISOString()
  };

  return { profile, sessions, moodLogs, cognitiveResult };
}
